#!/usr/bin/env python
"""Build the catalogue from tool pages generated by make wiki-tools.

Generated pages live in docs/reference/tools/ and are grouped by registry organization.
The authored introduction is docs/reference/tools.md. This script runs after mendel docs;
build_catalogue also accepts a temporary directory for validation without writing to docs.
"""

import sys
from pathlib import Path

TOOLS_DIR = Path(__file__).parent.parent / "docs" / "reference" / "tools"
OUT = TOOLS_DIR / "catalogue.md"

HEADER = """<!-- Generated by tools/generate_tools_catalogue.py. Do not edit: `make wiki-tools`
     overwrites it on every build. -->

# Catalogue

Every tool in the registry this site was built against, grouped by the org that supplies it.
"""


def build_catalogue(tools_dir: Path) -> str:
    """The catalogue's content for the tool pages found under `tools_dir`, or `""` if none."""
    by_org: dict[str, list[Path]] = {}
    for path in sorted(tools_dir.glob("*/*.md")):
        by_org.setdefault(path.parent.name, []).append(path)

    if not by_org:
        return ""

    lines = [HEADER]
    for org in sorted(by_org):
        lines.append(f"## {org}\n")
        for path in sorted(by_org[org], key=lambda p: p.stem):
            lines.append(f"- [{org}/{path.stem}]({org}/{path.name})")
        lines.append("")

    return "\n".join(lines) + "\n"


def main() -> int:
    content = build_catalogue(TOOLS_DIR)

    if not content:
        print(
            "generate_tools_catalogue: no tool pages under docs/reference/tools/ — "
            "run `mendel docs` (or `make wiki-tools`) first",
            file=sys.stderr,
        )
        return 1

    OUT.write_text(content, encoding="utf-8")
    tool_count = sum(1 for line in content.splitlines() if line.startswith("- ["))
    org_count = sum(1 for line in content.splitlines() if line.startswith("## "))
    relative = OUT.relative_to(Path(__file__).parent.parent)
    print(f"wrote {relative} ({tool_count} tools, {org_count} orgs)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
